/**
 * dsh-material-icon-theme — host half.
 *
 * Owns the vendored Material Icon Theme assets and serves one icon per request:
 *
 *   GET /material-icon-theme/<percent-encoded file or folder name>?d=0|1&o=0|1
 *     d=1  resolve the name as a directory (folder icon)
 *     o=1  that directory is expanded (folder-open variant)
 *
 * The client half only sets `background-image`; the mapping tables never leave
 * the host. Assets come from `assets/` next to this package (generated by
 * `scripts/vendor-icons.mjs`).
 *
 * Exports: `inject`, `PREFIX`, `loadIndex`, `resolveIcon`, `createRoute`, `apply`.
 * `createRoute()` returns `{ handler, cache }` and also sets `handler.cache` to
 * the same `Map` (exposed so tests can assert cache eviction).
 */
import { readFileSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { isAbsolute, join, relative, resolve as resolvePath } from 'node:path';
import { fileURLToPath } from 'node:url';

export const inject = ['webServer'];

/** HTTP prefix owned by this plugin; it must be unique among host routes. */
export const PREFIX = '/material-icon-theme';

/** `<package root>/assets`, resolved relative to this module. */
const DEFAULT_ASSETS_DIR = fileURLToPath(new URL('../assets/', import.meta.url));
const ICON_CACHE_LIMIT = 512;
const SVG_CONTENT_TYPE = 'image/svg+xml; charset=utf-8';

/** Parsed index cache keyed by assets directory, so `index.json` is read once. */
const indexCache = new Map();

/**
 * Read `<assetsDir>/index.json` (memoized per assets directory).
 * @param {string} [assetsDir]
 * @returns {{version: string, definitions: Record<string,string>, fileNames: Record<string,string>,
 *   fileExtensions: Record<string,string>, folderNames: Record<string,string>,
 *   folderNamesExpanded: Record<string,string>, defaults: Record<string,string>}}
 */
export function loadIndex(assetsDir = DEFAULT_ASSETS_DIR) {
  const dir = resolvePath(assetsDir);
  const cached = indexCache.get(dir);
  if (cached) return cached;
  const index = JSON.parse(readFileSync(join(dir, 'index.json'), 'utf8'));
  indexCache.set(dir, index);
  return index;
}

/**
 * Resolve a file/folder name to a vendored SVG basename (e.g. `tsconfig.svg`).
 * Order matches VS Code: exact name, case-insensitive name, longest extension
 * chain, theme default. Directories additionally pick the expanded table.
 *
 * @param {ReturnType<typeof loadIndex>} index
 * @param {string} name
 * @param {{isDir?: boolean, expanded?: boolean}} [options]
 * @returns {string|undefined} basename, or `undefined` when a table/definition is missing
 */
export function resolveIcon(index, name, { isDir = false, expanded = false } = {}) {
  if (!index || typeof name !== 'string' || name.length === 0) return undefined;
  return isDir ? resolveFolderIcon(index, name, expanded) : resolveFileIcon(index, name);
}

function resolveFileIcon(index, name) {
  // 1+2. `fileNames` exact, then case-insensitive.
  const fileNames = index.fileNames;
  if (fileNames) {
    const exact = fileNames[name];
    if (typeof exact === 'string') return definitionBasename(index, exact);
    const lower = fileNames[name.toLowerCase()];
    if (typeof lower === 'string') return definitionBasename(index, lower);
  }
  // 3. Extension chain, longest suffix first: `a.spec.ts` -> `spec.ts` -> `ts`.
  const fileExtensions = index.fileExtensions;
  if (fileExtensions) {
    for (let dot = name.indexOf('.', 1); dot !== -1; dot = name.indexOf('.', dot + 1)) {
      const candidate = name.slice(dot + 1).toLowerCase();
      if (!candidate) continue;
      const iconId = fileExtensions[candidate];
      if (typeof iconId !== 'string') continue;
      const basename = definitionBasename(index, iconId);
      if (basename) return basename;
    }
  }
  // 4. Theme default (`file.svg`).
  return defaultBasename(index, 'file');
}

function resolveFolderIcon(index, name, expanded) {
  const table = expanded ? index.folderNamesExpanded : index.folderNames;
  if (!table) return undefined;
  let iconId = table[name];
  if (typeof iconId !== 'string') iconId = table[name.toLowerCase()];
  if (typeof iconId === 'string') {
    const basename = definitionBasename(index, iconId);
    if (basename) return basename;
  }
  return defaultBasename(index, expanded ? 'folderOpen' : 'folder');
}

/** Map an icon id through `index.definitions`; `undefined` when the id is missing. */
function definitionBasename(index, iconId) {
  const definitions = index.definitions;
  if (!definitions || typeof iconId !== 'string') return undefined;
  const basename = definitions[iconId];
  return typeof basename === 'string' && basename.length > 0 ? basename : undefined;
}

/** `index.defaults` normally stores vendored basenames (e.g. `file.svg`). */
function defaultBasename(index, key) {
  const defaults = index.defaults;
  if (!defaults) return undefined;
  const value = defaults[key];
  if (typeof value !== 'string' || value.length === 0) return undefined;
  // Tolerate an index whose defaults still hold icon ids (`file`) instead of
  // basenames (`file.svg`): map through definitions when possible.
  return definitionBasename(index, value) || value;
}

/**
 * Build the prefix-route handler.
 *
 * @param {{index: object, assetsDir?: string, readSvg?: (file: string) => Promise<string|Buffer>,
 *   cacheLimit?: number}} options
 * @returns {{handler: (req: object, res: object) => Promise<void>, cache: Map<string, Buffer>}}
 */
export function createRoute({
  index,
  assetsDir = DEFAULT_ASSETS_DIR,
  readSvg = readFile,
  cacheLimit = ICON_CACHE_LIMIT,
} = {}) {
  if (!index) throw new TypeError('createRoute: index is required');
  const iconsDir = join(resolvePath(assetsDir), 'icons');
  /** basename -> SVG bytes; cleared wholesale once `cacheLimit` is reached. */
  const cache = new Map();

  async function handler(req, res) {
    const method = typeof req.method === 'string' ? req.method.toUpperCase() : 'GET';
    if (method !== 'GET' && method !== 'HEAD') {
      // No body is read: the route owns the full response.
      respond(res, 405, { allow: 'GET, HEAD' });
      return;
    }

    let url;
    try {
      url = new URL(req.url || '/', 'http://localhost');
    } catch {
      respond(res, 404, {});
      return;
    }

    const prefix = `${PREFIX}/`;
    if (!url.pathname.startsWith(prefix)) {
      respond(res, 404, {});
      return;
    }
    // The pathname is exactly one percent-encoded segment; `/` would be a path.
    const encoded = url.pathname.slice(prefix.length);
    if (encoded.length === 0 || encoded.includes('/')) {
      respond(res, 404, {});
      return;
    }

    let name;
    try {
      name = decodeURIComponent(encoded);
    } catch {
      respond(res, 400, {});
      return;
    }
    if (!isSafeName(name)) {
      respond(res, 404, {});
      return;
    }

    const isDir = url.searchParams.get('d') === '1';
    const expanded = url.searchParams.get('o') === '1';
    const iconName = resolveIcon(index, name, { isDir, expanded });
    if (!iconName) {
      respond(res, 404, {});
      return;
    }

    const file = join(iconsDir, iconName);
    if (!isInside(iconsDir, file)) {
      respond(res, 404, {});
      return;
    }

    let body = cache.get(iconName);
    if (!body) {
      let data;
      try {
        data = await readSvg(file);
      } catch {
        // ENOENT / unreadable assets / fully missing assets dir.
        respond(res, 404, {});
        return;
      }
      body = Buffer.isBuffer(data) ? data : Buffer.from(data);
      if (cache.size >= cacheLimit) cache.clear();
      cache.set(iconName, body);
    }

    respond(res, 200, {
      'content-type': SVG_CONTENT_TYPE,
      'content-length': String(body.length),
      'cache-control': 'public, max-age=31536000, immutable',
      'x-content-type-options': 'nosniff',
    }, method === 'HEAD' ? undefined : body);
  }

  // Tests can inspect/reuse the Map; the shape stays `Map<basename, Buffer>`.
  handler.cache = cache;
  return { handler, cache };
}

/**
 * Register the icon prefix route when the plugin is applied by the host.
 * @param {{effect: Function, webServer: {register: Function}}} ctx
 */
export function apply(ctx) {
  const index = loadIndex();
  ctx.effect(
    () => ctx.webServer.register({ kind: 'prefix', path: PREFIX, handler: createRoute({ index }).handler }),
    'material-icon-theme: icon route',
  );
}

function respond(res, status, headers, body) {
  res.writeHead(status, headers);
  res.end(body);
}

/** Reject empty names, path separators, NUL bytes and `..` traversal. */
function isSafeName(name) {
  if (name.length === 0) return false;
  if (name.includes('/') || name.includes('\\') || name.includes('\0')) return false;
  return !name.includes('..');
}

/** True when `child` is strictly inside `parent` (no traversal, no escape). */
function isInside(parent, child) {
  const rel = relative(parent, child);
  return rel.length > 0 && !rel.startsWith('..') && !isAbsolute(rel);
}
